1	"use client";
2	
3	import { useState, useCallback, useRef } from 'react';
4	
5	export type PhotoMagicState = 'idle' | 'processing' | 'result' | 'error';
6	
7	export interface PhotoMagicResult {
8	  imageUrl: string;
9	  originalImageUrl?: string;
10	  prompt: string;
11	}
12	
13	// Use relative path through Next.js rewrite proxy (works via tunnel + localhost)
14	const API_BASE = '/bot-api/photo-magic';
15	
16	export function usePhotoMagic() {
17	  const [state, setState] = useState<PhotoMagicState>('idle');
18	  const [progress, setProgress] = useState(0);
19	  const [progressText, setProgressText] = useState('');
20	  const [result, setResult] = useState<PhotoMagicResult | null>(null);
21	  const [error, setError] = useState<string | null>(null);
22	  const [sourceImage, setSourceImage] = useState<string | null>(null);
23	  const [prompt, setPrompt] = useState('');
24	  const abortRef = useRef<AbortController | null>(null);
25	
26	  const processSSE = useCallback(async (response: Response, userPrompt: string, originalUrl?: string) => {
27	    const reader = response.body?.getReader();
28	    if (!reader) throw new Error('No response stream');
29	
30	    const decoder = new TextDecoder();
31	    let buffer = '';
32	
33	    while (true) {
34	      const { done, value } = await reader.read();
35	      if (done) break;
36	
37	      buffer += decoder.decode(value, { stream: true });
38	      const lines = buffer.split('\n');
39	      buffer = lines.pop() || '';
40	
41	      for (const line of lines) {
42	        if (!line.startsWith('data: ')) continue;
43	        try {
44	          const data = JSON.parse(line.slice(6));
45	
46	          if (data.type === 'progress') {
47	            setProgress(data.progress ?? 0);
48	            setProgressText(data.message ?? '');
49	          } else if (data.type === 'complete' || data.type === 'result') {
50	            const imageUrl = data.imageUrl?.startsWith('http')
51	              ? data.imageUrl
52	              : `${API_BASE}/result/${data.filename || data.imageUrl}`;
53	            setResult({ imageUrl, originalImageUrl: originalUrl, prompt: userPrompt });
54	            setProgress(100);
55	            setState('result');
56	            return;
57	          } else if (data.type === 'error') {
58	            throw new Error(data.message || 'Generation failed');
59	          }
60	        } catch (e) {
61	          // skip malformed SSE lines
62	        }
63	      }
64	    }
65	  }, []);
66	
67	  const pollStatus = useCallback(async (promptId: string, userPrompt: string, originalUrl?: string) => {
68	    const maxAttempts = 120;
69	    for (let i = 0; i < maxAttempts; i++) {
70	      if (abortRef.current?.signal.aborted) return;
71	      await new Promise(r => setTimeout(r, 2000));
72	
73	      const res = await fetch(`${API_BASE}/status/${promptId}`, { signal: abortRef.current?.signal });
74	      const data = await res.json();
75	
76	      if (data.status === 'processing') {
77	        setProgress(data.progress ?? Math.min(90, (i / maxAttempts) * 100));
78	        setProgressText(data.message ?? 'Generating...');
79	      } else if (data.status === 'complete') {
80	        const imageUrl = data.imageUrl?.startsWith('http')
81	          ? data.imageUrl
82	          : `${API_BASE}/result/${data.filename || data.imageUrl}`;
83	        setResult({ imageUrl, originalImageUrl: originalUrl, prompt: userPrompt });
84	        setProgress(100);
85	        setState('result');
86	        return;
87	      } else if (data.status === 'error') {
88	        throw new Error(data.message || 'Generation failed');
89	      }
90	    }
91	    throw new Error('Generation timed out');
92	  }, []);
93	
94	  const handleResponse = useCallback(async (response: Response, userPrompt: string, originalUrl?: string) => {
95	    if (!response.ok) {
96	      const errBody = await response.text();
97	      throw new Error(errBody || `Server error ${response.status}`);
98	    }
99	
100	    const contentType = resp...

