12	export interface PhotoMagicViewProps {
13	  /** Optional initial prompt passed from voice command or taskbar */
14	  initialPrompt?: string;
15	}
16	
17	export default function PhotoMagicView({ initialPrompt }: PhotoMagicViewProps) {
18	  const {
19	    state,
20	    progress,
21	    progressText,
22	    result,
23	    error,
24	    sourceImage,
25	    prompt: activePrompt,
26	    generate,
27	    inpaint,
28	    reset,
29	    editAgain,
30	  } = usePhotoMagic();
31	
32	  const [promptText, setPromptText] = useState(initialPrompt || '');
33	  const [selectedFile, setSelectedFile] = useState<File | null>(null);
34	  const [filePreview, setFilePreview] = useState<string | null>(null);
35	  const [inpaintMode, setInpaintMode] = useState(false);
36	  const [maskBlob, setMaskBlob] = useState<Blob | null>(null);
37	  const [showMultiImages, setShowMultiImages] = useState(false);
38	  const [additionalFiles, setAdditionalFiles] = useState<Array<{ file: File; preview: string }>>([]);
39	  /** Gallery card that matches the image currently loaded as the active file (for focus ring) */
40	  const [gallerySelectedFilename, setGallerySelectedFilename] = useState<string | null>(null);
41	  const promptInputRef = useRef<HTMLInputElement>(null);
42	
43	  const handleFile = useCallback((file: File) => {
44	    setGallerySelectedFilename(null);
45	    setSelectedFile(file);
46	    setFilePreview(URL.createObjectURL(file));
47	    setInpaintMode(false);
48	    setMaskBlob(null);
49	  }, []);
50	
51	  const handleGallerySelect = useCallback(
52	    async (url: string, filename: string) => {
53	      try {
54	        const res = await fetch(url);
55	        if (!res.ok) return;
56	        const blob = await res.blob();
57	        const file = new File([blob], filename, { type: blob.type || 'image/png' });
58	        if (filePreview) URL.revokeObjectURL(filePreview);
59	        setSelectedFile(file);
60	        setFilePreview(URL.createObjectURL(file));
61	        setInpaintMode(false);
62	        setMaskBlob(null);
63	        setGallerySelectedFilename(filename);
64	      } catch {
65	        /* silent */
66	      }
67	    },
68	    [filePreview],
69	  );
70	
71	  const handleClearFile = useCallback(() => {
72	    if (filePreview) URL.revokeObjectURL(filePreview);
73	    setGallerySelectedFilename(null);
74	    setSelectedFile(null);
75	    setFilePreview(null);
76	    setInpaintMode(false);
77	    setMaskBlob(null);
78	  }, [filePreview]);
79	
80	  const handleAddFile = useCallback((index: number, file: File) => {
81	    setAdditionalFiles(prev => {
82	      const next = [...prev];
83	      if (next[index]) URL.revokeObjectURL(next[index].preview);
84	      next[index] = { file, preview: URL.createObjectURL(file) };
85	      return next;
86	    });
87	  }, []);
88	
89	  const handleRemoveAdditional = useCallback((index: number) => {
90	    setAdditionalFiles(prev => {
91	      const next = [...prev];
92	      if (next[index]) URL.revokeObjectURL(next[index].preview);
93	      next.splice(index, 1);
94	      return next;
95	    });
96	  }, []);
97	
98	  const handleMaskReady = useCallback((blob: Blob) => {
99	    setMaskBlob(blob);
100	    setInpaintMode(false);
101	  }, []);
102	
103	  const handleSubmit = useCallback(() => {
104	    const text = promptText.trim();
105	    if (!text && !selectedFile) return;
106	
107	    const p = text || 'enhance this image';
108	
109	    if (selectedFile && maskBlob) {
110	      // Inpaint mode
111	      inpaint(p, selectedFile, maskBlob);
