1	import { NextRequest, NextResponse } from 'next/server';
2	
3	/**
4	 * Generic image proxy — fetches an external image URL server-side and returns
5	 * the bytes directly. This avoids CORS, CSP, referrer-policy, and hotlinking
6	 * issues that plague external images inside sandboxed iframes (Wonder Canvas).
7	 *
8	 * Usage: /api/image-proxy?url=https://upload.wikimedia.org/...
9	 */
10	export async function GET(request: NextRequest) {
11	  const url = request.nextUrl.searchParams.get('url');
12	  if (!url) {
13	    return NextResponse.json({ error: 'Missing url parameter' }, { status: 400 });
14	  }
15	
16	  // Basic validation — only allow http/https URLs
17	  let parsed: URL;
18	  try {
19	    parsed = new URL(url);
20	    if (!['http:', 'https:'].includes(parsed.protocol)) {
21	      return NextResponse.json({ error: 'Invalid protocol' }, { status: 400 });
22	    }
23	  } catch {
24	    return NextResponse.json({ error: 'Invalid URL' }, { status: 400 });
25	  }
26	
27	  try {
28	    const upstream = await fetch(url, {
29	      headers: {
30	        'User-Agent': 'Mozilla/5.0 (compatible; PearlOS/1.0)',
31	        'Accept': 'image/*,*/*',
32	      },
33	      redirect: 'follow',
34	      signal: AbortSignal.timeout(10_000),
35	    });
36	
37	    if (!upstream.ok) {
38	      return NextResponse.json(
39	        { error: `Upstream returned ${upstream.status}` },
40	        { status: 502 },
41	      );
42	    }
43	
44	    const contentType = upstream.headers.get('content-type') || 'image/jpeg';
45	    const body = await upstream.arrayBuffer();
46	
47	    return new NextResponse(body, {
48	      status: 200,
49	      headers: {
50	        'Content-Type': contentType,
51	        'Cache-Control': 'public, max-age=86400, s-maxage=86400',
52	        'Access-Control-Allow-Origin': '*',
53	      },
54	    });
55	  } catch (err) {
56	    console.error('[api/image-proxy] error:', err);
57	    return NextResponse.json({ error: 'Image fetch failed' }, { status: 502 });
58	  }
59	}
60

