1	"use client";
2	
3	import { useState, useRef, useCallback, type DragEvent, type ChangeEvent } from 'react';
4	
5	interface DropZoneProps {
6	  onFile: (file: File) => void;
7	  file: File | null;
8	  onClear: () => void;
9	  previewUrl: string | null;
10	}
11	
12	export function DropZone({ onFile, file, onClear, previewUrl }: DropZoneProps) {
13	  const [dragging, setDragging] = useState(false);
14	  const inputRef = useRef<HTMLInputElement>(null);
15	  const dragCountRef = useRef(0);
16	
17	  const handleDragEnter = useCallback((e: DragEvent) => {
18	    e.preventDefault();
19	    e.stopPropagation();
20	    dragCountRef.current++;
21	    setDragging(true);
22	  }, []);
23	
24	  const handleDragLeave = useCallback((e: DragEvent) => {
25	    e.preventDefault();
26	    e.stopPropagation();
27	    dragCountRef.current--;
28	    if (dragCountRef.current <= 0) {
29	      dragCountRef.current = 0;
30	      setDragging(false);
31	    }
32	  }, []);
33	
34	  const handleDragOver = useCallback((e: DragEvent) => {
35	    e.preventDefault();
36	    e.stopPropagation();
37	  }, []);
38	
39	  const handleDrop = useCallback((e: DragEvent) => {
40	    e.preventDefault();
41	    e.stopPropagation();
42	    dragCountRef.current = 0;
43	    setDragging(false);
44	
45	    const droppedFile = e.dataTransfer.files?.[0];
46	    if (droppedFile && droppedFile.type.startsWith('image/')) {
47	      onFile(droppedFile);
48	    }
49	  }, [onFile]);
50	
51	  const handleFileChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
52	    const selected = e.target.files?.[0];
53	    if (selected && selected.type.startsWith('image/')) {
54	      onFile(selected);
55	    }
56	    // reset so same file can be re-selected
57	    if (inputRef.current) inputRef.current.value = '';
58	  }, [onFile]);
59	
60	  const handleClick = useCallback(() => {
61	    if (!file) inputRef.current?.click();
62	  }, [file]);
63	
64	  return (
65	    <div
66	      className={`pm-dropzone ${dragging ? 'dragging' : ''}`}
67	      onDragEnter={handleDragEnter}
68	      onDragLeave={handleDragLeave}
69	      onDragOver={handleDragOver}
70	      onDrop={handleDrop}
71	      onClick={handleClick}
72	      role="button"
73	      tabIndex={0}
74	      aria-label={file ? `Selected: ${file.name}` : 'Drop a photo or click to browse'}
75	    >
76	      <span className="pm-corner pm-corner--tl" />
77	      <span className="pm-corner pm-corner--br" />
78	
79	      {previewUrl && file ? (
80	        <>
81	          <img src={previewUrl} alt="Selected" className="pm-dropzone__preview" />
82	          <div className="pm-dropzone__subtitle">{file.name}</div>
83	          <button
84	            className="pm-dropzone__clear"
85	            onClick={(e) => { e.stopPropagation(); onClear(); }}
86	            aria-label="Remove image"
87	          >
88	            ✕
89	          </button>
90	        </>
91	      ) : (
92	        <>
93	          <div className="pm-dropzone__icon">
94	            {dragging ? '✦' : '◐'}
95	          </div>
96	          <div className="pm-dropzone__title">
97	            {dragging ? 'Release to enchant' : 'Drop a photo to edit'}
98	          </div>
99	          <div className="pm-dropzone__subtitle">
100	            or click to browse · png, jpg, webp

